      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is SystemConfig) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is WindowSummary) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is ThumbnailPermissions) {
      buffer.putUint8(139);
